      reg_aw_pending <= 1'b0;
      reg_w_pending <= 1'b0;
    end else begin
      if (w_aw_hs) begin
        reg_aw_pending <= 1'b1;
        reg_awaddr_hold <= i_axi_awaddr;
      end
      if (w_w_hs) begin
        reg_w_pending <= 1'b1;
        reg_wdata_hold <= i_axi_wdata;
        reg_wstrb_hold <= i_axi_wstrb;
      end
    end
