    w_port_2_value[17] = reg_port_2_pending;
    w_port_2_value[16] = reg_port_2_overflow;
    w_port_2_value[15] = reg_port_2_done;
  end

  // Parameterized register group monitor: indexed field updates and per-copy storage.
  generate
    for (genvar gen_idx = 0; (gen_idx < PARA_MONITOR_COUNT) && (gen_idx < LPARA_MONITOR_MAX_COUNT); gen_idx++) begin : gen_monitor
    assign w_monitor_threshold_nxt[gen_idx] = (w_we_monitor[gen_idx] & (|reg_wmask[23:20])) ? ((reg_wdata[23:20] & reg_wmask[23:20]) | (reg_monitor_threshold[gen_idx] & ~reg_wmask[23:20])) : reg_monitor_threshold[gen_idx];
    assign w_monitor_capture_nxt[gen_idx] = (w_we_monitor[gen_idx] & (|reg_wmask[19])) ? ((reg_wdata[19] & reg_wmask[19]) | ((i_hw_we_monitor_capture[gen_idx] ? i_hw_wdata_monitor_capture[gen_idx] : reg_monitor_capture[gen_idx]) & ~reg_wmask[19])) : (i_hw_we_monitor_capture[gen_idx] ? i_hw_wdata_monitor_capture[gen_idx] : reg_monitor_capture[gen_idx]);
    assign w_monitor_error_nxt[gen_idx] = (i_hw_we_monitor_error[gen_idx]) ? i_hw_wdata_monitor_error[gen_idx] : ((w_we_monitor[gen_idx] & (|reg_wmask[18])) ? (reg_monitor_error[gen_idx] & ~(reg_wdata[18] & reg_wmask[18])) : reg_monitor_error[gen_idx]);
    assign w_monitor_pending_nxt[gen_idx] = (i_hw_we_monitor_pending[gen_idx]) ? i_hw_wdata_monitor_pending[gen_idx] : ((w_we_monitor[gen_idx] & (|reg_wmask[17])) ? (reg_monitor_pending[gen_idx] & (reg_wdata[17] | ~reg_wmask[17])) : reg_monitor_pending[gen_idx]);
    assign w_monitor_overflow_nxt[gen_idx] = (i_hw_we_monitor_overflow[gen_idx]) ? i_hw_wdata_monitor_overflow[gen_idx] : ((w_we_monitor[gen_idx] & (|reg_wstrb)) ? '0 : reg_monitor_overflow[gen_idx]);
    assign w_monitor_match_nxt[gen_idx] = (i_hw_we_monitor_match[gen_idx]) ? i_hw_wdata_monitor_match[gen_idx] : (w_rd_monitor[gen_idx] ? '0 : reg_monitor_match[gen_idx]);
    always_comb begin : p_com_monitor_value
      w_monitor_value[gen_idx] = '0;
      w_monitor_value[gen_idx][31:24] = i_monitor_sample_count[gen_idx];
      w_monitor_value[gen_idx][23:20] = reg_monitor_threshold[gen_idx];
      w_monitor_value[gen_idx][19] = reg_monitor_capture[gen_idx];
      w_monitor_value[gen_idx][18] = reg_monitor_error[gen_idx];
      w_monitor_value[gen_idx][17] = reg_monitor_pending[gen_idx];
      w_monitor_value[gen_idx][16] = reg_monitor_overflow[gen_idx];
      w_monitor_value[gen_idx][15] = reg_monitor_match[gen_idx];
    end
    // One state bank per generated register index.
    always_ff @(posedge w_clk_reg, negedge w_rst_n_reg) begin : p_ff_monitor
      if (!w_rst_n_reg) begin
        reg_monitor_threshold[gen_idx] <= 4'h0;
        reg_monitor_capture[gen_idx] <= 1'h0;
        reg_monitor_error[gen_idx] <= 1'h0;
        reg_monitor_pending[gen_idx] <= 1'h0;
        reg_monitor_overflow[gen_idx] <= 1'h0;
        reg_monitor_match[gen_idx] <= 1'h0;
      end else begin
        reg_monitor_threshold[gen_idx] <= w_monitor_threshold_nxt[gen_idx];
        reg_monitor_capture[gen_idx] <= w_monitor_capture_nxt[gen_idx];
        reg_monitor_error[gen_idx] <= w_monitor_error_nxt[gen_idx];
        reg_monitor_pending[gen_idx] <= w_monitor_pending_nxt[gen_idx];
        reg_monitor_overflow[gen_idx] <= w_monitor_overflow_nxt[gen_idx];
        reg_monitor_match[gen_idx] <= w_monitor_match_nxt[gen_idx];
      end
    end
    end
  endgenerate
  assign o_monitor_threshold = reg_monitor_threshold;
  assign o_monitor_capture = reg_monitor_capture;
  assign o_monitor_error = reg_monitor_error;
  assign o_monitor_pending = reg_monitor_pending;
  assign o_monitor_overflow = reg_monitor_overflow;
  assign o_monitor_match = reg_monitor_match;

  // Unmapped register addresses return zero and generate DECERR.
  always_comb begin : p_com_reg_read_decode
    w_rdata_nxt = '0;
    w_addr_mapped = 1'b0;
    case (32'(reg_addr))
      LPARA_ENGINE_OFFSET: begin w_rdata_nxt = w_engine_value; w_addr_mapped = 1'b1; end
      LPARA_PORT_0_OFFSET: begin w_rdata_nxt = w_port_0_value; w_addr_mapped = 1'b1; end
      LPARA_PORT_1_OFFSET: begin w_rdata_nxt = w_port_1_value; w_addr_mapped = 1'b1; end
      LPARA_PORT_2_OFFSET: begin w_rdata_nxt = w_port_2_value; w_addr_mapped = 1'b1; end
      (LPARA_MONITOR_BASE_OFFSET + (32'd0 * LPARA_MONITOR_OFFSET_STRIDE)): if (PARA_MONITOR_COUNT > 32'd0) begin w_rdata_nxt = w_monitor_value[0]; w_addr_mapped = 1'b1; end
      (LPARA_MONITOR_BASE_OFFSET + (32'd1 * LPARA_MONITOR_OFFSET_STRIDE)): if (PARA_MONITOR_COUNT > 32'd1) begin w_rdata_nxt = w_monitor_value[1]; w_addr_mapped = 1'b1; end
      (LPARA_MONITOR_BASE_OFFSET + (32'd2 * LPARA_MONITOR_OFFSET_STRIDE)): if (PARA_MONITOR_COUNT > 32'd2) begin w_rdata_nxt = w_monitor_value[2]; w_addr_mapped = 1'b1; end
      (LPARA_MONITOR_BASE_OFFSET + (32'd3 * LPARA_MONITOR_OFFSET_STRIDE)): if (PARA_MONITOR_COUNT > 32'd3) begin w_rdata_nxt = w_monitor_value[3]; w_addr_mapped = 1'b1; end
      default: begin w_rdata_nxt = '0; w_addr_mapped = 1'b0; end
    endcase
  end

endmodule
